from AlgorithmImports import *
from collections import deque
from datetime import timedelta, time


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        # Assumption: profit target is a 20% gain from the filled entry price.
        self.profit_target_pct = 0.20

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe.Strikes(-100, 100).Expiration(
                timedelta(days=0),
                timedelta(days=365)
            )
        )

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_signal_time = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_contract = None
        self.entry_fill_price = None
        self.block_entries_on_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        # With New York as the algorithm time zone, this consolidator is aligned
        # to New York five-minute clock boundaries (e.g. first RTH bar ends 09:35).
        close = float(bar.Close)
        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        current_fast = sum(self.fast_closes) / 5.0
        current_slow = sum(self.slow_closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        bar_time = bar.EndTime.time()
        if bullish_cross and time(9, 45) <= bar_time <= time(14, 30):
            self.pending_signal_time = bar.EndTime

    def OnData(self, data):
        self.HandleUnexpectedSpyPosition()
        self.HandleExpirationProtection()
        self.HandleHeldOptionExit(data)

        if self.pending_signal_time != self.Time:
            return

        self.pending_signal_time = None

        if self.block_entries_on_date == self.Time.date():
            return

        if self.HasOptionHolding() or self.HasOpenEntryOrder():
            return

        self.TryEnterCall(data)

    def TryEnterCall(self, data):
        spy_bar = data.Bars.get(self.spy)
        if spy_bar is None or spy_bar.Close <= 0:
            self.Debug(f"{self.Time}: Skipped entry selection: no current SPY TradeBar.")
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{self.Time}: Skipped entry selection: no SPY option chain.")
            return

        minimum_expiry_date = self.Time.date() + timedelta(days=7)
        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain.Contracts
            if contract.Expiry.date() >= minimum_expiry_date
        })

        if not eligible_expiries:
            self.Debug(f"{self.Time}: Skipped entry selection: no expiry at least 7 calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = float(spy_bar.Close) * 1.01

        candidates = [
            contract
            for contract in chain.Contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: Skipped entry selection: no qualifying call "
                f"for expiry {selected_expiry}."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"{self.Time}: Submitted entry for {selected.Symbol}, "
            f"expiry {selected.Expiry.date()}, strike {selected.Strike}."
        )

    def HandleHeldOptionExit(self, data):
        if not self.HasOptionHolding() or self.entry_fill_price is None:
            return

        if self.HasOpenExitOrder():
            return

        contract = self.held_contract
        quote = data.QuoteBars.get(contract)

        if quote is not None and quote.Bid is not None and quote.Ask is not None:
            bid = float(quote.Bid.Close)
            ask = float(quote.Ask.Close)

            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                target_price = self.entry_fill_price * (1.0 + self.profit_target_pct)

                if midpoint >= target_price:
                    self.SubmitExit("profit target")
                    return

        expiry_date = contract.ID.Date.date()
        if self.Time.date() == self.PreviousSpyTradingDate(expiry_date):
            if self.Time.hour == 15 and self.Time.minute == 45:
                self.SubmitExit("15:45 pre-expiration time stop")

    def HandleExpirationProtection(self):
        if not self.HasOptionHolding():
            return

        expiry_date = self.held_contract.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.block_entries_on_date = self.Time.date()

            if not self.HasOpenExitOrder():
                self.SubmitExit("expiration protection")

    def HandleUnexpectedSpyPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        open_spy_orders = self.Transactions.GetOpenOrders(self.spy)
        if open_spy_orders:
            return

        self.block_entries_on_date = self.Time.date()
        self.Debug(
            f"{self.Time}: Unexpected SPY equity position ({quantity}) from "
            "exercise/assignment; submitting liquidation."
        )
        self.MarketOrder(self.spy, -quantity)

    def SubmitExit(self, reason):
        if not self.HasOptionHolding():
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(order.Id, f"Replacing open exit: {reason}")

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
            self.Debug(f"{self.Time}: Submitted exit for {self.held_contract}: {reason}.")

    def PreviousSpyTradingDate(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def HasOptionHolding(self):
        return (
            self.held_contract is not None
            and self.Portfolio[self.held_contract].Quantity != 0
        )

    def HasOpenEntryOrder(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        )

    def HasOpenExitOrder(self):
        return (
            self.exit_ticket is not None
            and self.exit_ticket.Status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        )

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
                self.held_contract = order_event.Symbol
                self.entry_fill_price = float(order_event.FillPrice)
                self.Debug(
                    f"{self.Time}: Entry fill for {order_event.Symbol} at "
                    f"{self.entry_fill_price:.2f}."
                )

            if order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"{self.Time}: Entry order did not complete for {order_event.Symbol}.")

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: Exit fill for {order_event.Symbol} at "
                    f"{float(order_event.FillPrice):.2f}."
                )

                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.held_contract = None
                    self.entry_fill_price = None
                    self.exit_ticket = None
