class FiveMinuteSpyCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.spy_option = self.AddOption("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy_option].SetDataNormalizationMode(
            DataNormalizationMode.Raw
        )
        self.OptionChainProvider.SetOptionContractFilter(
            self.spy_option, lambda universe: universe.Strikes(-100, 100)
            .Expiration(timedelta(0), timedelta(365))
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None
        self.minute_buckets = {}

        # Default target is 20%; can be overridden by a backtest parameter.
        self.profit_target = float(self.GetParameter("profitTarget") or 0.20)

        self.held_contract = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.spy_liquidation_order_id = None
        self.blocked_entry_date = None

    def OnData(self, data: Slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration_processing()

        if self.held_contract is not None and self.Portfolio[self.held_contract].Invested:
            self._evaluate_time_stop()
            self._evaluate_profit_target(data)

        if self.spy in data.Bars:
            self._process_spy_minute_bar(data.Bars[self.spy], data)

    def _process_spy_minute_bar(self, bar: TradeBar, data: Slice):
        end = bar.EndTime.replace(second=0, microsecond=0)
        minutes_to_boundary = (5 - (end.minute % 5)) % 5
        bucket_end = end + timedelta(minutes=minutes_to_boundary)

        if bucket_end not in self.minute_buckets:
            self.minute_buckets[bucket_end] = {}

        self.minute_buckets[bucket_end][end] = bar

        # A completed five-minute regular-session bar ends at an exact boundary.
        if end.minute % 5 != 0:
            return

        bucket = self.minute_buckets.pop(end, {})
        expected_ends = {end - timedelta(minutes=i) for i in range(5)}

        # Do not synthesize a five-minute bar when any constituent minute is missing.
        if set(bucket.keys()) != expected_ends:
            return

        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if previous_ready else None
        previous_slow = self.slow.Current.Value if previous_ready else None

        close = bucket[end].Close
        self.fast.Update(end, close)
        self.slow.Update(end, close)

        if not (previous_ready and self.fast.IsReady and self.slow.IsReady):
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if bullish_cross and self._is_entry_time(end):
            self._try_enter(data)

    def _is_entry_time(self, time):
        current = time.time()
        return current >= datetime(2000, 1, 1, 9, 45).time() and current <= datetime(
            2000, 1, 1, 14, 30
        ).time()

    def _try_enter(self, data: Slice):
        if self.blocked_entry_date == self.Time.date():
            return

        if self.entry_order_id is not None or self.exit_order_id is not None:
            return

        if self.held_contract is not None and self.Portfolio[self.held_contract].Invested:
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Skipped entry: SPY has no valid current price.")
            return

        contracts = []
        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Right == OptionRight.Call:
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no option chain/contracts in current Slice.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        expirations = sorted(
            {contract.Expiry.date() for contract in contracts
             if contract.Expiry.date() >= minimum_expiry}
        )

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven calendar days away.")
            return

        expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_order_id = self.MarketOrder(selected.Symbol, 1).OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol}, expiry {expiry}, "
            f"strike {selected.Strike}"
        )

    def _evaluate_profit_target(self, data: Slice):
        if self.exit_order_id is not None or self.entry_price is None:
            return

        if self.held_contract not in data.QuoteBars:
            return

        quote = data.QuoteBars[self.held_contract]
        bid = quote.Bid.Close if quote.Bid is not None else 0
        ask = quote.Ask.Close if quote.Ask is not None else 0

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * (1 + self.profit_target):
            self._submit_exit(
                f"Profit target reached for {self.held_contract} at midpoint {midpoint:.2f}"
            )

    def _evaluate_time_stop(self):
        if self.exit_order_id is not None or self.held_contract is None:
            return

        expiry = self.held_contract.ID.Date.date()
        previous_trading_day = self._previous_trading_day(expiry)

        if (
            self.Time.date() == previous_trading_day
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self._submit_exit(
                f"15:45 pre-expiration exit for {self.held_contract}"
            )

    def _handle_expiration_processing(self):
        if self.held_contract is None or not self.Portfolio[self.held_contract].Invested:
            return

        expiry = self.held_contract.ID.Date.date()
        if self.Time.date() >= expiry:
            self.blocked_entry_date = self.Time.date()
            self._submit_exit(
                f"Expiration processing liquidation for {self.held_contract}"
            )

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0 or self.spy_liquidation_order_id is not None:
            return

        self.Debug(
            f"Unexpected SPY position ({quantity}) from exercise/assignment; liquidating."
        )
        self.spy_liquidation_order_id = self.MarketOrder(self.spy, -quantity).OrderId

    def _submit_exit(self, reason):
        if self.held_contract is None:
            return

        if self.exit_order_id is not None:
            return

        if self.entry_order_id is not None:
            self.Transactions.CancelOrder(self.entry_order_id)

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        self.exit_order_id = self.MarketOrder(self.held_contract, -quantity).OrderId
        self.Debug(f"Exit submitted: {reason}")

